#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, a[1000];
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);
    if (n) {
        int last = a[n - 1];
        for (int i = n - 1; i > 0; i--)
            a[i] = a[i - 1];
        a[0] = last;
    }
    if (n == 0)
        puts("EMPTY");
    for (int i = 0; i < n; i++)
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    return 0;
}

