void reverse_range(int *first, int *end) {
    while (first < end) {
        --end;
        if (first >= end)
            break;
        int t = *first;
        *first = *end;
        *end = t;
        ++first;
    }
}
int main(void) {
    int n, lo, hi, a[100];
