int symmetric(const int *a, int n) {
    if (n == 0)
        return 1;
    const int *l = a, *r = a + n - 1;
    while (l < r) {
        if (*l != *r)
            return 0;
        l++;
        r--;
    }
    return 1;
}
int main(void) {
    int n, a[1000];
