#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp_int(const void *p, const void *q) {
    int a = *(const int *)p, b = *(const int *)q;
    return (a > b) - (a < b);
}
int main(void) {
    int n, t, a[100];
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);
    qsort(a, (size_t)n, sizeof *a, cmp_int);
    int best = a[0];
    for (int i = 1; i < n; i++)
        if (abs(a[i] - t) < abs(best - t))
            best = a[i];
    printf("%d\n", best);
    return 0;
}

