#include <ctype.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;
void destroy(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}
Node *read_list(int n) {
    Node *head = NULL, **tail = &head;
    for (int i = 0; i < n; i++) {
        Node *node = malloc(sizeof *node);
        if (!node) {
            destroy(head);
            exit(1);
        }
        scanf("%d", &node->value);
        node->next = NULL;
        *tail = node;
        tail = &node->next;
    }
    return head;
}
void print_list(const Node *head) {
    if (!head) {
        puts("EMPTY");
        return;
    }
    for (const Node *p = head; p; p = p->next)
        printf("%d%c", p->value, p->next ? ' ' : '\n');
}
int main(void) {
    int n;
    scanf("%d", &n);
    Node *head = read_list(n);
    print_list(head);
    destroy(head);
    return 0;
}

