} Meeting;
int meeting_cmp(const void *p, const void *q) {
    const Meeting *a = p, *b = q;
    return (a->end > b->end) - (a->end < b->end);
}
int main(void) {
    int n;
    Meeting a[100];
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d%d", &a[i].start, &a[i].end);
